    public static class ZofiaNałkowska
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Dla prawdziwego szczęścia warto później trochę pocierpieć. (…) Tak, tak, za wszystko dobre w życiu trzeba drogo zapłacić! (…) Są kobiety, które wcale szczęścia nie zaznały i nawet nie mają czego wspominać.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Dziwne, jakie złoża cierpienia czekają w człowieku całkiem gotowe, przeznaczone dla drugiego człowieka.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Jedyną rzeczą, po jakiej poznaję swoje uczucie, jest cierpienie.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Jestem kimś, kto musi żyć powoli. Widzę wtedy urok życia, doznaję go w całości.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Moja miłość jest na całej przestrzeni mnie, na wszystkich szczeblach, jestem nią cała objęta, nie chcę zostawić dla siebie nic.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Co dla jednych jest podłogą, dla drugich jest sufitem.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Jest się takim, jak myślą ludzie, nie jak myślimy o sobie my, jest się takim, jak miejsce, w którym się jest.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Czyżby naprawdę miłość niemożliwa była bez kochania?", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Nie cierpię: w delirium męki przeszłam tę granicę, poza którą wrażenia nie różniczkują się już na radość i ból, za którą noc nieszczęścia nie przeciwstawia się już dniowi.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Poznawanie życia nie nauczyło mnie nic, nie doprowadziło do żadnej syntezy. Im więcej się o nim wie, tym trudniej sformułować uogólnienie. W życiu wszystko wzajemnie sobie przeczy. Nauka jest bardziej konsekwentna.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Zazdrość jest przejawem czysto biologicznej natury. W zawiści zaś jest coś, co poniża piękność duszy, wciąga ją w grę pasji małych i głupich.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "By służyć życiu, nie należy go kochać zbyt silnie.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Jam już widziała tyle zła, które wypłynęło z dobra --takiego zła, z którym walczyć nie wolno – bo z niego daleko gdzieś – znowu wypłynie dobro…", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Jest to czarowny stosunek między mężczyzną i kobietą, którego nie psuje miłość. Jest w nim namiętność zakwefiona, nie stępiona tkliwością, nie osłabiona zbliżeniem, jest wrogość, nie dopuszczająca odkrywania stron słabych, wzajemne hiperbolizowanie się, prowadzące do szczytów patosu.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Wierność cenna jest tylko w takiej kobiecie, którą ona coś kosztuje.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Ludzie ludziom zgotowali ten los.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "W Niemczech, można powiedzieć, ludzie umieją coś zrobić – z niczego…", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Było to tym gorsze według niej, że zamknięte w dziedzinie spekulacji, w obrębie projektu. Rzecz dokonana miałaby wytłumaczenie w wielkiej komplikacji powodujących ją okoliczności i przyczyn. Rzecz pomyślana nie ma złagodzeń, jest prosta i niewątpliwa.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Dla mnie niedostępne są takie etyczne subtelności jak zbrodnie myślane… Jedynym możliwym sprawdzianem jest czyn, tylko czyn leży w obrębie odpowiedzialności ludzkiej --", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Jest w tym właśnie jakieś obrzydliwe tchórzostwo czekać tak na tę śmierć, jak zwierzę, póki sama nie przyjdzie. Jest małoduszność w takim bezwarunkowym godzeniu się na życie.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Nie jestem kobieta wyzwolona, nie jestem nawet wyzwalająca się kobieta. Boję się wolności dla siebie jak opuszczenia i śmierci. Boję się jej jak nieskończoności. Właśnie chcę oddana być w niewolę i móc w niewolę brać. Chcę pętać sobą – i chodzić w cudzym zaczarowaniu.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Nie jest jeden człowiek. Jest szereg kawałków czasu, nawleczonych na nitkę jednej pamięci.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Człowiek robi się podobny do swojego losu.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Mnie się wydaje, że człowiek rodzi się każdy możliwy. Właśnie tak muszę to powiedzieć: każdy możliwy. Wszystko z nim może być – najbardziej odmienne, najbardziej mu zaprzeczające, najdalsze.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Alboż nie jesteśmy wolni? Niepodległość – a jest już, jest. Są i granice. Mamy wszystko to, co jest gdzie indziej, czegośmy innym tak zazdrościli. Jest łapownictwo rodzime, prywata, protekcja, rządy motłochu, wielkie afery, wielkie majątki, interes, interes przede wszystkim.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Człowiek chciałby się kończyć na swej skórze – ale się nie kończy.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Tańczyć – jest to właściwie: iść nigdzie.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "W formule: Bóg i Ojczyzna – zawiera się więc antynomia i bluźnierstwo. Bóg jest tym, co ludzi w najwyższych ich tęsknotach godzi i jednoczy, ojczyzna tym, co według najwyższych haseł – dzieli. Ojczyzna przywraca politeizm: każda armia do swego Boga modli się o zwycięstwo.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Największym urokiem świata jest urok drugiego człowieka.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Każda miłość ma chwile martwe, ale wówczas powinno się nad nią czuwać.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Należy unikać brania gotowej piękności prosto z życia. Model nie powinien sam przez się być doskonałym dziełem sztuki, ale zaledwie okazją do samodzielnego poszukiwania piękności.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Nie lubi się ludzi, którym wyrządziło się krzywdę. Ma się żal do nich, że byli przyczyną tego, co nas zawstydza, chociaż w istocie byli tylko pretekstem.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Religia nie powinna zawierać się w formułkach, a w duszy.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Słusznie jest gdzieś tam powiedziane, że estetyczna twórczość kobiety wyraża zawsze tylko niedobór uczuciowy.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "W haremie tęsknot samotna dziś błądzę,<br />Spragniona świeżych ust, krwi i gorąca,<br />Z pod kwiatów senną wygrzebałam rządzę<br />I patrzę smutnie w pobladłą twarz słońca.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Wystarczy zwrócić uwagę na człowieka, by stał się pociągający i na swój sposób piękny.", Author = "Zofia Nałkowska" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Zofia_Nałkowska", Text = "Za zadanie wzięłam sobie obalić ten przesąd niemądry, że kobieta, co skończyła uniwersytet, przestaje być kobietą.", Author = "Zofia Nałkowska" },
        };
    }
}